import yaml,duckdb,pathlib
contract=yaml.safe_load(open('docs/data_contract.yaml')); c=duckdb.connect('salesforce.duckdb',read_only=True)
for layer,sch in [('staging_contract','staging'),('intermediate_models','intermediate'),('marts_models','marts')]:
 models=contract[layer]['tables'] if layer=='staging_contract' else contract['modeling_spec'][layer]
 for m in models:
  name=m['name']; expected=[x['name'] for x in m['columns']]; actual=[x[0] for x in c.execute(f'describe {sch}.{name}').fetchall()]
  if expected!=actual: print('DIFF',name,expected,actual)
print('history counts/unique', c.execute('select count(*),count(distinct history_unique_key) from staging.stg_salesforce__account_history').fetchone())
for t,col in [('stg_salesforce__contact','contact_id'),('stg_salesforce__opportunity','opportunity_id'),('stg_salesforce__user','user_id'),('stg_salesforce__lead','lead_id'),('stg_salesforce__event','event_id'),('stg_salesforce__task','task_id')]:
 print(t,c.execute(f'select count(*),count(distinct {col}) from staging.{t}').fetchone())
print('sql',len(list(pathlib.Path('sql').rglob('*.sql')),' ;:',sum(p.read_text().rstrip().endswith(';') for p in pathlib.Path('sql').rglob('*.sql')))
